require "test_helper"

# The Security MCP tools are admin only (generated by maquina:security): only
# someone on the backstage list sees them. A member's token must not learn they
# exist: they are absent from tools/list and a call gets the same -32602 as an
# unknown tool. McpTestHelper turns any MCP feature flag on and puts mcp_admin
# on the backstage list, so access is the only gate tested.
class Mcp::Tools::SecurityTest < ActionDispatch::IntegrationTest
  TOOLS = Mcp::Tools::Security::DEFINITIONS.map { |definition| definition[:name] }
  ARGUMENTS = {"unban_address" => {ip: "203.0.113.9"}}.freeze
  ADDRESS = "203.0.113.9"

  # The test environment's cache is a null store, where a ban is never
  # written. A memory store lets a test ban an address and read it back.
  setup do
    @rack_attack_store = Rack::Attack.cache.store
    Rack::Attack.cache.store = ActiveSupport::Cache::MemoryStore.new
  end

  teardown do
    Rack::Attack.cache.store = @rack_attack_store
  end

  test "an admin sees the tools" do
    assert_equal TOOLS, TOOLS & listed_tools(users(:mcp_admin))
  end

  test "a member does not see the tools" do
    assert_empty TOOLS & listed_tools(users(:mcp_member))
  end

  test "a member calling any of the tools gets unknown tool" do
    token = oauth_token_for(users(:mcp_member), scope: "read write")

    TOOLS.each do |name|
      mcp_post({jsonrpc: "2.0", id: 1, method: "tools/call", params: {name: name, arguments: ARGUMENTS.fetch(name, {})}}, token: token)

      assert_equal(-32602, response.parsed_body.dig("error", "code"), name)
    end
  end

  test "recent_blocks lists refusals newest first and says whether the address is banned now" do
    ban(ADDRESS)
    Security::AbuseEvent.record!(kind: "blocked", rule: "fail2ban/scanners", ip: ADDRESS, request_method: "GET", path: "/.env")

    event = call_tool("recent_blocks")["events"].first

    assert_equal ["/.env", ADDRESS, true], event.values_at("path", "ip", "banned_now")
  end

  test "security_summary counts refusals per kind" do
    Security::AbuseEvent.record!(kind: "throttled", rule: "req/ip", ip: ADDRESS, request_method: "GET", path: "/")

    summary = call_tool("security_summary")

    assert_equal 1, summary["total"]
    assert_equal 1, summary.dig("by_kind", "throttled")
  end

  test "unban_address lifts the ban" do
    skip "Read-only tools: rails g maquina:security --mcp-write adds unban_address" unless TOOLS.include?("unban_address")
    ban(ADDRESS)

    result = call_tool("unban_address", {ip: ADDRESS}, scope: "read write")

    assert_equal [ADDRESS, true, false], result.values_at("ip", "was_banned", "banned_now")
    assert_not Rack::Attack.banned?(ADDRESS)
  end

  test "unban_address refuses something that is not one address" do
    skip "Read-only tools: rails g maquina:security --mcp-write adds unban_address" unless TOOLS.include?("unban_address")

    ["not-an-ip", "203.0.113.0/24"].each do |ip|
      mcp_post({method: "tools/call", params: {name: "unban_address", arguments: {ip: ip}}}, token: oauth_token_for(users(:mcp_admin), scope: "read write"))

      assert response.parsed_body.dig("result", "isError"), ip
    end
  end

  private

  def ban(ip)
    Rack::Attack::Fail2Ban.filter("scanner:#{ip}", maxretry: 1, findtime: 1.minute, bantime: 1.hour) { true }
    assert Rack::Attack.banned?(ip)
  end

  def call_tool(name, arguments = {}, scope: "read")
    mcp_post({method: "tools/call", params: {name: name, arguments: arguments}}, token: oauth_token_for(users(:mcp_admin), scope: scope))
    assert_response :success
    result = response.parsed_body["result"]
    assert_equal false, result["isError"], result.dig("content", 0, "text")
    result["structuredContent"]
  end


  def listed_tools(user)
    mcp_post({jsonrpc: "2.0", id: 1, method: "tools/list", params: {}}, token: oauth_token_for(user, scope: "read write"))
    response.parsed_body.dig("result", "tools").map { |tool| tool["name"] }
  end
end
